package com.ledger.app.data.db

import androidx.room.AutoMigration
import androidx.room.Database
import androidx.room.RoomDatabase
import androidx.room.migration.Migration
import androidx.sqlite.db.SupportSQLiteDatabase

@Database(
    entities = [
        TransactionEntity::class, RuleEntity::class,
        CategoryEntity::class, OwnAccountEntity::class, OwnAccountNameEntity::class,
        BudgetEntity::class,
    ],
    version = 9,
    exportSchema = true,
    // Migrations that only add tables or columns are generated by Room and
    // checked at compile time against the exported schemas:
    //   v1 -> v2  adds the `categories` table.
    //   v2 -> v3  adds `own_accounts` and `transactions.selfTransfer` (default 0;
    //             rows are re-checked once the user adds their own accounts).
    //   v3 -> v4  adds `own_account_names`, `own_accounts.institution` and
    //             `transactions.referenceKeys` (filled in on first use).
    // From v4 -> v5 on, migrations also move data, so they are written by hand.
    autoMigrations = [
        AutoMigration(from = 1, to = 2),
        AutoMigration(from = 2, to = 3),
        AutoMigration(from = 3, to = 4),
    ],
)
abstract class LedgerDatabase : RoomDatabase() {
    abstract fun transactionDao(): TransactionDao
    abstract fun ruleDao(): RuleDao
    abstract fun categoryDao(): CategoryDao
    abstract fun ownAccountDao(): OwnAccountDao
    abstract fun ownAccountNameDao(): OwnAccountNameDao
    abstract fun budgetDao(): BudgetDao

    companion object {
        const val NAME = "ledger.db"

        /**
         * Splits categories into money in and money out.
         *
         * Written by hand because existing categories need a side assigned, and new
         * ones must be added without changing the user's order or names.
         *
         * The old "Other" served both directions. Spending filed under it moves to
         * "Misc", and "Other" becomes the income catch-all.
         *
         * Every statement is safe to run twice, and nothing is deleted.
         */
        val MIGRATION_4_5 = object : Migration(4, 5) {
            /**
             * Older categories that are clearly money in. "Income" is no longer seeded,
             * but older ledgers have it.
             */
            private val LEGACY_INCOME = listOf("Income")

            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL("ALTER TABLE categories ADD COLUMN kind TEXT NOT NULL DEFAULT 'OUT'")

                // Give spending its own catch-all before "Other" changes sides.
                val catchAll = DefaultCategories.SPEND_CATCH_ALL
                val legacy = DefaultCategories.INCOME_CATCH_ALL
                db.execSQL(
                    "UPDATE transactions SET category = ? WHERE category = ? AND direction = 'DEBIT'",
                    arrayOf(catchAll, legacy),
                )
                db.execSQL(
                    "UPDATE rules SET category = ? WHERE category = ? AND direction = 'DEBIT'",
                    arrayOf(catchAll, legacy),
                )

                // Assign sides. Anything not named here, including the user's own
                // categories, keeps the default (money out).
                val income = DefaultCategories.ALL
                    .filter { it.kind == CategoryKind.IN }
                    .map { it.name } + LEGACY_INCOME
                db.execSQL(
                    "UPDATE categories SET kind = 'IN' WHERE name IN (${placeholders(income.size)})",
                    income.toTypedArray(),
                )
                db.execSQL(
                    "UPDATE categories SET kind = 'SHARED' WHERE name = ?",
                    arrayOf(DefaultCategories.TRANSFERS),
                )

                // Add the new defaults at the end so the user's order is kept. OR IGNORE
                // relies on the unique name index.
                DefaultCategories.ALL.forEach { category ->
                    db.execSQL(
                        "INSERT OR IGNORE INTO categories (name, position, enabled, kind) " +
                            "SELECT ?, (SELECT COALESCE(MAX(position), -1) + 1 FROM categories), 1, ?",
                        arrayOf(category.name, category.kind.name),
                    )
                }
            }

            private fun placeholders(n: Int) = List(n) { "?" }.joinToString(",")
        }

        /**
         * Gives each wallet its own row instead of one row per phone number.
         *
         * One number can carry two wallets (MTN MoMo and GhanaPay, say), each with its
         * own name. A wallet is now identified by number and provider, which needs a
         * new primary key, so both tables are rebuilt.
         *
         * `institution` becomes NOT NULL DEFAULT '' because it is part of a unique
         * index, and SQLite treats every null as different.
         *
         * Nothing is lost: existing rows keep their number, label, provider and names.
         */
        val MIGRATION_5_6 = object : Migration(5, 6) {
            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL(
                    "CREATE TABLE IF NOT EXISTS `own_accounts_new` (" +
                        "`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, " +
                        "`key` TEXT NOT NULL, `identifier` TEXT NOT NULL, `label` TEXT NOT NULL, " +
                        // No SQL DEFAULT, because the entity declares none and Room compares
                        // them. The INSERT below fills the value in for existing rows.
                        "`addedAt` INTEGER NOT NULL, `institution` TEXT NOT NULL)"
                )
                db.execSQL(
                    "INSERT INTO `own_accounts_new` (`key`, `identifier`, `label`, `addedAt`, `institution`) " +
                        "SELECT `key`, `identifier`, `label`, `addedAt`, COALESCE(`institution`, '') FROM `own_accounts`"
                )
                db.execSQL("DROP TABLE `own_accounts`")
                db.execSQL("ALTER TABLE `own_accounts_new` RENAME TO `own_accounts`")
                db.execSQL(
                    "CREATE UNIQUE INDEX IF NOT EXISTS `index_own_accounts_key_institution` " +
                        "ON `own_accounts` (`key`, `institution`)"
                )

                // Names now point at the wallet's row instead of its number. A name
                // whose wallet can't be found is dropped, since it could never match.
                db.execSQL(
                    "CREATE TABLE IF NOT EXISTS `own_account_names_new` (" +
                        "`name` TEXT NOT NULL, `accountId` INTEGER NOT NULL, `display` TEXT NOT NULL, " +
                        "PRIMARY KEY(`name`))"
                )
                db.execSQL(
                    "INSERT INTO `own_account_names_new` (`name`, `accountId`, `display`) " +
                        "SELECT n.`name`, a.`id`, n.`display` FROM `own_account_names` n " +
                        "JOIN `own_accounts` a ON a.`key` = n.`accountKey`"
                )
                db.execSQL("DROP TABLE `own_account_names`")
                db.execSQL("ALTER TABLE `own_account_names_new` RENAME TO `own_account_names`")
                db.execSQL(
                    "CREATE INDEX IF NOT EXISTS `index_own_account_names_accountId` " +
                        "ON `own_account_names` (`accountId`)"
                )
            }
        }

        /**
         * Adds `categories.favorite` and the budgets table.
         *
         * Favourites are the categories pickers show first. They are copied from the
         * old setup shortlist, which was stored by disabling the categories not
         * picked. If no category is disabled, the shortlist was never used, so no
         * favourites are set and pickers use the default order.
         *
         * Then every category is enabled again, so none are hidden. A category hidden
         * on purpose in the editor comes back too, because the two can't be told apart.
         */
        val MIGRATION_6_7 = object : Migration(6, 7) {
            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL("ALTER TABLE categories ADD COLUMN favorite INTEGER NOT NULL DEFAULT 0")
                db.execSQL(
                    "UPDATE categories SET favorite = enabled " +
                        "WHERE EXISTS (SELECT 1 FROM categories WHERE enabled = 0)"
                )
                db.execSQL("UPDATE categories SET enabled = 1")
                db.execSQL(
                    "CREATE TABLE IF NOT EXISTS `budgets` (" +
                        "`category` TEXT NOT NULL, `limitMinor` INTEGER NOT NULL, " +
                        "`updatedAt` INTEGER NOT NULL, PRIMARY KEY(`category`))"
                )
            }
        }

        /**
         * v7 -> v8: adds the cash ledger and drops the `senders` table, since every
         * supported provider is now always captured.
         *
         * `cashMove` starts null everywhere. Older messages can't be re-read (their
         * text was never stored), so older withdrawals are moved to cash by hand.
         */
        val MIGRATION_7_8 = object : Migration(7, 8) {
            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL("DROP TABLE IF EXISTS `senders`")
                db.execSQL("ALTER TABLE transactions ADD COLUMN cashMove TEXT")
            }
        }

        /**
         * v8 -> v9: adds `transactions.chainBreak`. Existing rows start at 0, because
         * their balance was already checked when they were captured.
         */
        val MIGRATION_8_9 = object : Migration(8, 9) {
            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL("ALTER TABLE transactions ADD COLUMN chainBreak INTEGER NOT NULL DEFAULT 0")
            }
        }
    }
}
